records.formula:
collected_partial_numbers = the matching numbers beginning with the letter P carried by the items that are not reconciled
narrowed_set = { item : item is not reconciled } ∪ { item : item is reconciled AND its matching number is not in collected_partial_numbers }
the checks are then applied to narrowed_set, in the order written above

map = { }
if not is_zero( company_currency , remaining ) : map[ company_currency ] = ( remaining , 1 )
if item_currency ≠ company_currency and not is_zero( item_currency , remaining_curr ) : map[ item_currency ] = ( remaining_curr , accounting_rate( item , item_currency ) )
if item_currency = company_currency and the account is receivable or payable and remaining ≠ 0 and counterpart_currency ≠ company_currency :
    rate = platform_rate( item , other_item , counterpart_currency )
    residual_in_foreign = round_to( counterpart_currency , remaining × rate )
    if residual_in_foreign ≠ 0 : map[ counterpart_currency ] = ( residual_in_foreign , rate )
else if item_currency = counterpart_currency ≠ company_currency and remaining_curr ≠ 0 : map[ counterpart_currency ] = ( remaining_curr , accounting_rate( item , item_currency ) )

if debit_fully_matched :
    debit_exchange = remaining_debit_amount_currency − partial_debit_amount_currency
    if not is_zero( debit_currency , debit_exchange ) :
        record an exchange line for the debit item , fixing its FOREIGN residual by debit_exchange
        remaining_debit_amount_currency ← remaining_debit_amount_currency − debit_exchange

if credit_fully_matched :
    credit_exchange = remaining_credit_amount_currency + partial_credit_amount_currency
    if not is_zero( credit_currency , credit_exchange ) :
        record an exchange line for the credit item , fixing its FOREIGN residual by credit_exchange
        remaining_credit_amount_currency ← remaining_credit_amount_currency + credit_exchange

if debit_fully_matched :
    debit_exchange = remaining_debit_amount − partial_amount
    if not is_zero( company , debit_exchange ) : record a COMPANY fix of debit_exchange for the debit item ; remaining_debit_amount ← remaining_debit_amount − debit_exchange ; and when debit_currency = company_currency also remaining_debit_amount_currency ← remaining_debit_amount_currency − debit_exchange
else :
    debit_exchange = partial_debit_amount − partial_amount
    if compare( company , debit_exchange , 0 ) > 0 : same two updates

if credit_fully_matched :
    credit_exchange = remaining_credit_amount + partial_amount
    if not is_zero( company , credit_exchange ) : record a COMPANY fix of credit_exchange for the credit item ; remaining_credit_amount ← remaining_credit_amount − credit_exchange ; and when credit_currency = company_currency also remaining_credit_amount_currency ← remaining_credit_amount_currency − credit_exchange
else :
    credit_exchange = partial_amount − partial_credit_amount
    if compare( company , credit_exchange , 0 ) < 0 : same two updates

sign = +1 for a plain entry or an outbound document , −1 otherwise
for each payment-term item , in order of due date then date :
    installment = ( number , item , due date or the item's date , amount_residual , amount_residual_currency , amount_residual × −sign , amount_residual_currency × −sign , type , whether the item is reconciled )

group the installments by the currency of their item
for each currency :
    residual          = Σ amount_residual          over the installments of that currency
    residual_currency = Σ amount_residual_currency over the installments of that currency
    if currency = the screen currency                          : contribution = residual_currency
    else if currency ≠ company currency AND the screen currency = company currency : contribution = convert( residual_currency , from currency to the company currency , for the company , at the payment date )
    else                                                        : contribution = convert( residual , from the company currency to the screen currency , for the company , at the payment date )
total = Σ contribution

for each eligible item : ( item , matched foreign amount = − the item's foreign residual , matched balance = that amount converted to the company currency at the payment date )
open_amount_currency = payment_difference × ( −1 when the direction is outbound , +1 when inbound )
open_balance         = convert( open_amount_currency , from the payment currency to the company currency , for the company , at the payment date )

is_structured_for_country( reference , country_code ) :
    r ← sanitize( reference )
    if country_code is BE : return Belgian(r)
    if country_code is FI : return Finnish(r)
    if country_code is NO : return NorwegianSwedish(r)
    if country_code is SE : return NorwegianSwedish(r)
    if country_code is NL : return Dutch(r)
    if country_code is SI : return Slovenian(r)
    otherwise             : return International(r)

